// Availability Check Mode - Initialize variables (DB-backed, no Google Calendar)
const startDateTime = new Date($('When Executed by Another Workflow').first().json.startingDateAndTime).toISOString();
const endDateTime = new Date($('When Executed by Another Workflow').first().json.endingDateAndTime).toISOString();
const durationMinutes = parseInt($('When Executed by Another Workflow').first().json.durationInMinutes) || 60;
const existingAppointmentId = $('When Executed by Another Workflow').first().json.appointmentId
  ? Number($('When Executed by Another Workflow').first().json.appointmentId)
  : null;

const calendars = ($('Get Active Calendars').all() || [])
  .map(c => c.json)
  .filter(c => c && c.id != null);

const allAppointments = ($('Get Appointments In Range').all() || [])
  .map(a => a.json)
  .filter(a => a && a.id != null);

// Each calendar (consultorio) is available if there are no appointments
// overlapping the requested window for its calendar_source_id.
const calendarData = calendars.map(cal => {
  const calAppointments = allAppointments.filter(a =>
    a.calendar_source_id != null &&
    Number(a.calendar_source_id) === Number(cal.id)
  );
  return {
    calendarSourceId: Number(cal.id),
    googleCalendarId: cal.google_calendar_id,
    name: cal.name,
    calAppointments,
    isAvailable: calAppointments.length === 0
  };
});

return {
  json: {
    mode: 'checkAvailability',
    startDateTime,
    endDateTime,
    durationMinutes,
    existingAppointmentId,
    calendars: calendarData,
    allAppointments
  }
};

const availableCalendars = $input.first().json.calendars.filter(cal => cal.isAvailable === true);
const unAvailableCalendars = $input.first().json.calendars.filter(cal => cal.isAvailable === false);
const allAppointments = $input.first().json.allAppointments;

return {
  json: {
    mode: 'checkAvailability',
    availableCalendars,
    unAvailableCalendars,
    allAppointments
  }
};

const availableCalendars = $('Filter Available Calendars').first().json.availableCalendars || [];
const unAvailableCalendars = $('Filter Available Calendars').first().json.unAvailableCalendars || [];
const allAppointments = $('Filter Available Calendars').first().json.allAppointments || [];

const doctors = ($('Search Doctors').all() || [])
  .map(d => d.json)
  .filter(d => d && d.id);

const requestedDoctors = ($('Get_Request_Doctor').all() || [])
  .map(d => d.json)
  .filter(d => d && d.id);

// Doctors who are assignee of any appointment overlapping the requested window
const busyDoctorIds = new Set();
allAppointments.forEach(a => {
  if (a.assignee_id) busyDoctorIds.add(a.assignee_id);
});

const availableDoctors = doctors.filter(d => !busyDoctorIds.has(d.id));

const doctorWasSpecified = requestedDoctors.length > 0;
const requestedDoctor = doctorWasSpecified ? requestedDoctors[0] : null;

let isAvailableSpecifiedDoctor = false;
let finalAssignedDoctor = null;
let reason = null;

if (doctorWasSpecified) {
  isAvailableSpecifiedDoctor = availableDoctors.some(a => a.id === requestedDoctor.id);
  if (isAvailableSpecifiedDoctor) {
    finalAssignedDoctor = requestedDoctor;
  }
} else if (availableDoctors.length > 0) {
  finalAssignedDoctor = availableDoctors[0];
  reason = 'no_doctor_specified';
}

const assignedCalendar = availableCalendars[0] || null;

return {
  json: {
    mode: 'checkAvailability',
    doctors,
    availableCalendars,
    unAvailableCalendars,
    availableDoctors,
    busyDoctorIds: Array.from(busyDoctorIds),
    requestedDoctor,
    doctorWasSpecified,
    isAvailableSpecifiedDoctor,
    finalAssignedDoctor,
    reason,
    assignedCalendarSourceId: assignedCalendar ? assignedCalendar.calendarSourceId : null,
    assignedCalendarName: assignedCalendar ? assignedCalendar.name : null,
    assignedGoogleCalendarId: assignedCalendar ? assignedCalendar.googleCalendarId : null
  }
};

