// Build suggested time slots using durationInMinutes from input.
const calendars = ($('Get All Active Calendars').all() || [])
  .map(c => c.json || c)
  .filter(c => c && c.id != null);

const doctorSlots = ($('Select Available Doctors').all() || []).map(s => s.json);

const allAppointments = ($('Get Appointments In Range1').all() || [])
  .map(a => a.json)
  .filter(a => a && a.id != null);

const startTimeString = $('Set_StartingDateAndTime').first().json.scheduleStartingTime;
const endTimeString = $('Set_StartingDateAndTime').first().json.scheduleEndingTime;
const durationMinutes = parseInt($('When Executed by Another Workflow').first().json.durationInMinutes) || 60;

const localTimezone = 'America/Montevideo';
const startTime = DateTime.fromISO(startTimeString, { zone: localTimezone }).toJSDate();
const endTime = DateTime.fromISO(endTimeString, { zone: localTimezone }).toJSDate();
const intervalMinutes = durationMinutes;

const possibleAppointments = [];
let currentTime = new Date(startTime);

while (currentTime < endTime) {
  const slotEndTime = new Date(currentTime.getTime() + intervalMinutes * 60000);
  const currentLuxonTime = DateTime.fromJSDate(currentTime);

  // Step 1: doctors flagged as available in DB at this slot
  const doctorSlot = doctorSlots.find(slot => {
    const slotLuxonTime = DateTime.fromISO(slot.local_hour_tz);
    return slotLuxonTime.equals(currentLuxonTime);
  });

  let dbAvailableDoctors = [];
  if (doctorSlot && doctorSlot.ids_disponibles && doctorSlot.ids_disponibles.length > 0) {
    dbAvailableDoctors = doctorSlot.ids_disponibles;
  } else {
    currentTime.setMinutes(currentTime.getMinutes() + intervalMinutes);
    continue;
  }

  // Step 2: drop doctors with overlapping appointments (matched by assignee_id)
  const trulyAvailableDoctors = dbAvailableDoctors.filter(doctor => {
    const isBusy = allAppointments.some(appt => {
      const apptStart = new Date(appt.start_datetime);
      const apptEnd = new Date(appt.end_datetime);
      const overlaps = apptStart < slotEndTime && apptEnd > currentTime;
      if (!overlaps) return false;
      return appt.assignee_id === doctor.user_id;
    });
    return !isBusy;
  });

  if (trulyAvailableDoctors.length === 0) {
    currentTime.setMinutes(currentTime.getMinutes() + intervalMinutes);
    continue;
  }

  // Step 3: per consultorio (calendar_source), check if free at this slot
  for (const calendar of calendars) {
    const calendarSourceId = Number(calendar.id);
    const calendarName = calendar.name;
    const googleCalendarId = calendar.google_calendar_id;

    const isCalendarBusy = allAppointments.some(appt => {
      if (Number(appt.calendar_source_id) !== calendarSourceId) return false;
      const apptStart = new Date(appt.start_datetime);
      const apptEnd = new Date(appt.end_datetime);
      return apptStart < slotEndTime && apptEnd > currentTime;
    });

    if (!isCalendarBusy) {
      for (const doctor of trulyAvailableDoctors) {
        possibleAppointments.push({
          calendar_source_id: calendarSourceId,
          calendar_name: calendarName,
          google_calendar_id: googleCalendarId,
          fecha_cita: currentTime.toLocaleDateString('sv-SE'),
          hora_cita: currentTime.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: localTimezone }),
          start_datetime: currentTime.toISOString(),
          end_datetime: slotEndTime.toISOString(),
          user_id: doctor.user_id,
          user_name: doctor.user_name
        });
      }
    }
  }

  currentTime.setMinutes(currentTime.getMinutes() + intervalMinutes);
}

return possibleAppointments.map(appt => ({ json: appt }));

return {
  json: {
    isAvailable: false,
    suggestedTimes: $input.all().map(i => i.json)
  }
};
